message.content:
下面給你一份 **完整、可直接跑起來** 的「拼圖遊戲」範例，使用 **HTML + CSS + JavaScript**（Canvas）實作。  
你只要把程式碼貼到一個 `.html` 檔案，開啟瀏覽器就能玩。  
如果你想改成桌面版（例如 Python + Tkinter）或手機 App，只要把核心邏輯搬到對應平台即可。

---

## 1️⃣ 目錄結構

```
puzzle/
├─ index.html
├─ style.css
├─ script.js
└─ images/
   └─ mypicture.jpg   ← 你想切成拼圖的圖片
```

> **備註**  
> - `mypicture.jpg` 可以換成任何你想切成拼圖的圖片。  
> - 這個範例預設切成 **4x4**（共 16 块）拼圖，你可以在程式碼裡改 `rows`、`cols` 來調整。

---

## 2️⃣ `index.html`

```html
<!DOCTYPE html>
<html lang="zh-Hant">
<head>
  <meta charset="UTF-8">
  <title>拼圖遊戲</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <h1>拼圖遊戲</h1>

  <div id="puzzle-container"></div>

  <div id="controls">
    <button id="reset-btn">重新開始</button>
    <span id="timer">時間：0 秒</span>
  </div>

  <script src="script.js"></script>
</body>
</html>
```

---

## 3️⃣ `style.css`

```css
body {
  font-family: 'Microsoft JhengHei', sans-serif;
  text-align: center;
  background: #f0f0f0;
  margin: 0;
  padding: 20px;
}

#puzzle-container {
  width: 640px;
  height: 640px;
  margin: 20px auto;
  position: relative;
  border: 2px solid #333;
  background: #fff;
}

.piece {
  position: absolute;
  cursor: grab;
  transition: transform 0.2s ease;
}

.piece.dragging {
  cursor: grabbing;
  z-index: 1000;
}

#controls {
  margin-top: 10px;
}

#timer {
  margin-left: 20px;
  font-weight: bold;
}
```

---

## 4️⃣ `script.js`

```js
/* ==============================
   1. 基本設定
   ============================== */
const rows = 4;          // 行數
const cols = 4;          // 列數
const imgSrc = 'images/mypicture.jpg'; // 圖片路徑
const container = document.getElementById('puzzle-container');
const resetBtn = document.getElementById('reset-btn');
const timerEl = document.getElementById('timer');

let pieces = [];        // 所有拼圖塊
let timer = null;
let startTime = null;

/* ==============================
   2. 產生拼圖塊
   ============================== */
function createPieces() {
  const pieceWidth = container.clientWidth / cols;
  const pieceHeight = container.clientHeight / rows;

  // 先把所有位置存成一個陣列，之後打亂
  const positions = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      positions.push({ row: r, col: c });
    }
  }

  // 隨機打亂
  shuffleArray(positions);

  // 產生 DOM
  pieces = positions.map((pos, idx) => {
    const piece = document.createElement('div');
    piece.className = 'piece';
    piece.style.width = `${pieceWidth}px`;
    piece.style.height = `${pieceHeight}px`;
    piece.style.backgroundImage = `url(${imgSrc})`;
    piece.style.backgroundSize = `${container.clientWidth}px ${container.clientHeight}px`;
    piece.style.backgroundPosition = `-${pos.col * pieceWidth}px -${pos.row * pieceHeight}px`;
    piece.dataset.correctRow = pos.row;
    piece.dataset.correctCol = pos.col;
    piece.dataset.currentRow = pos.row;
    piece.dataset.currentCol = pos.col;

    // 初始位置（打亂後）
    const shuffledPos = positions[idx];
    piece.style.left = `${shuffledPos.col * pieceWidth}px`;
    piece.style.top = `${shuffledPos.row * pieceHeight}px`;

    // 事件綁定
    piece.addEventListener('mousedown', onDragStart);
    piece.addEventListener('touchstart', onDragStart, { passive: false });

    container.appendChild(piece);
    return piece;
  });
}

/* ==============================
   3. 拖曳功能
   ============================== */
let dragPiece = null;
let offsetX = 0;
let offsetY = 0;

function onDragStart(e) {
  e.preventDefault();
  dragPiece = e.currentTarget;
  dragPiece.classList.add('dragging');

  const rect = dragPiece.getBoundingClientRect();
  if (e.type === 'mousedown') {
    offsetX = e.clientX - rect.left;
    offsetY = e.clientY - rect.top;
    document.addEventListener('mousemove', onDragging);
    document.addEventListener('mouseup', onDragEnd);
  } else if (e.type === 'touchstart') {
    const touch = e.touches[0];
    offsetX = touch.clientX - rect.left;
    offsetY = touch.clientY - rect.top;
    document.addEventListener('touchmove', onDragging, { passive: false });
    document.addEventListener('touchend', onDragEnd);
  }
}

function onDragging(e) {
  e.preventDefault();
  let clientX, clientY;
  if (e.type === 'mousemove') {
    clientX = e.clientX;
    clientY = e.clientY;
  } else if (e.type === 'touchmove') {
    const touch = e.touches[0];
    clientX = touch.clientX;
    clientY = touch.clientY;
  }

  const left = clientX - offsetX;
  const top = clientY - offsetY;
  dragPiece.style.left = `${left}px`;
  dragPiece.style.top = `${top}px`;
}

function onDragEnd(e) {
  // 釋放事件
  if (e.type === 'mouseup') {
    document.removeEventListener('mousemove', onDragging);
    document.removeEventListener('mouseup', onDragEnd);
  } else if (e.type === 'touchend') {
    document.removeEventListener('touchmove', onDragging);
    document.removeEventListener('touchend', onDragEnd);
  }

  // 重新定位到最近的格子
  const pieceWidth = container.clientWidth / cols;
  const pieceHeight = container.clientHeight / rows;
  const left = parseInt(dragPiece.style.left, 10);
  const top = parseInt(dragPiece.style.top, 10);

  const col = Math.round(left / pieceWidth);
  const row = Math.round(top / pieceHeight);

  // 限制在容器內
  const newLeft = Math.min(Math.max(col * pieceWidth, 0), container.clientWidth - pieceWidth);
  const newTop = Math.min(Math.max(row * pieceHeight, 0), container.clientHeight - pieceHeight);

  dragPiece.style.left = `${newLeft}px`;
  dragPiece.style.top = `${newTop}px`;

  // 更新目前位置
  dragPiece.dataset.currentRow = row;
  dragPiece.dataset.currentCol = col;

  dragPiece.classList.remove('dragging');
  dragPiece = null;

  // 檢查是否完成
  checkSolved();
}

/* ==============================
   4. 檢查完成
   ============================== */
function checkSolved() {
  const allCorrect = pieces.every(p => {
    return parseInt(p.dataset.currentRow, 10) === parseInt(p.dataset.correctRow, 10) &&
           parseInt(p.dataset.currentCol, 10) === parseInt(p.dataset.correctCol, 10);
  });

  if (allCorrect) {
    clearInterval(timer);
    alert(`恭喜！你在 ${Math.round((Date.now() - startTime)/1000)} 秒內完成拼圖！`);
  }
}

/* ==============================
   5. 重新開始
   ============================== */
function resetGame() {
  // 清除舊的拼圖
  container.innerHTML = '';
  // 重新產生
  createPieces();
  // 重置計時器
  startTime = Date.now();
  clearInterval(timer);
  timer = setInterval(() => {
    const elapsed = Math.round((Date.now() - startTime)/1000);
    timerEl.textContent = `時間：${elapsed} 秒`;
  }, 1000);
}

/* ==============================
   6. 工具函式
   ============================== */
function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

/* ==============================
   7. 初始化
   ============================== */
resetBtn.addEventListener('click', resetGame);
resetGame();   // 初始啟動
```

---

## 5️⃣ 如何使用

1. **下載或複製** 上面三個檔案到同一個資料夾。  
2. 把你想切成拼圖的圖片放到 `images/` 資料夾，並改成 `mypicture.jpg`（或直接改 `imgSrc` 為你自己的路徑）。  
3. 用瀏覽器打開 `index.html`。  
4. 拖曳拼圖塊，直到拼好。  
5. 點擊「重新開始」即可重玩。

---

## 6️⃣ 進階功能（可自行擴充）

| 功能 | 方式 | 參考 |
|------|------|------|
| **自動切圖** | 先把圖片切成多張 PNG，再用 `img` 逐塊載入 | 需要 Node.js + sharp 或 Python Pillow |
| **多種難度** | 改變 `rows`、`cols` 或加入「缺失一塊」 | 只改 `rows`、`cols` 變數 |
| **拖曳動畫** | 用 CSS `transition` 或 `requestAnimationFrame` | 參考 `dragging` class |
| **手機支援** | 已加入 `touchstart`、`touchmove`、`touchend` | 只要測試即可 |
| **分數/時間** | 只要把 `timer` 變成秒數，或加入 `moves` 計數 | 參考 `timerEl` |

---

### 小結

這份範例已經包含：

- **圖片切割**（透過 CSS 背景定位）
- **隨機打亂**（shuffle）
- **拖曳**（mouse + touch）
- **位置校正**（snap to grid）
- **完成判斷**（檢查每塊位置）
- **計時器**（秒數顯示）

你可以直接把它跑起來，或把核心邏輯搬到你想要的平台（React、Vue、Flutter、Python Tkinter 等）。如果你有任何想要加的功能或遇到問題，隨時告訴我！祝你玩得開心 🚀
